/// 界面文案表（zh-Hant），编号与 docs/UI-COPY.md 一一对应。
extension CopyTables {
    static let zhHantJSON = #"""
{"A01": "👇 請在下面完成校園網登入吧。放心，咱們程式絕對不會偷偷儲存或上傳你的明文密碼喔 🔒💖！", "A02": "🚀 已經呼叫你的預設瀏覽器打開登入頁啦！", "A03": "🛡️ 沒幫你自動打開：因為發現這個網址不在咱們吉大的 jlu.edu.cn 網域下喔 🧐", "A04": "🌐 在瀏覽器裡輸完密碼成功登入後，記得回到這裡點一下「已完成登入」喔 🙋‍♂️！整個過程咱們程式連碰都不會碰你的明文密碼，安全感拉滿 🛡️✨！", "A05": "⚠️ 請先再三確認你現在連的 Wi-Fi 真的是學校官方的 JLU.WIFI 或 JLU.PC，而且這個網址看著靠譜可信，咱們再繼續往下走喔 🕵️‍♂️✨！", "A06": "🔄 重新打開登入頁", "A07": "🦸‍♂️ 我確認過了，仍要打開這個頁面", "A08": "✖️ 算了，取消", "A09": "🎉 我已完成登入啦！", "A10": "🚨 警惕！這個登入頁面的網址居然不是 jlu.edu.cn 結尾的喔 🧐", "A11": "⚠️ 只有當你百分百確認目前連的 Wi-Fi 是學校正牌的 JLU.WIFI / JLU.PC 時，才點繼續喔；", "A12": "🙅‍♂️ 如果連上了名字奇奇怪怪的可疑野雞網路，千萬別在裡面輸入你的寶貴帳號和密碼呀 🛡️！", "A13": "😭 哎呀，校園網認證還沒跑通呢", "A14": "🔄 重新測一次", "A15": "💡 如果你現在確實在校外（比如用手機熱點或家裡寬頻 🏠），想看校內系統得走 WebVPN 通道喔 🌉；要是你明明插著網路線坐在寢室裡，那就先點重試認證看看 🔄。點下面的按鈕會直接幫你打開 WebVPN 並貼心複製好帳號噠 📋✨！", "A16": "🌉 打開吉大 WebVPN", "A17": "🔑 複製密碼", "A18": "🐾 超簡單三步走：網頁打開後在「師生普通登錄」裡選統一身份認證 👉 直接貼上帳號（已經幫你複製好啦 📋）👉 輸入密碼登入 👉 搞定後回來點一下「重測」就 OK 啦 🎉！", "A19": "✅ 帳號已經幫你複製好啦：{…} ✨", "A20": "🙈 你還沒有儲存過帳號呢——先去「設定」裡填一次吧 ✍️！", "A21": "🤔 電腦裡還沒有存過密碼喔——先去「設定」裡儲存一次吧 💾！", "A22": "🔐 密碼已複製！為了保護隱私，60 秒後會自動清空剪貼簿喔 ⏱️🛡️", "A23": "🏫 校園網歡迎入口網站", "A24": "🌐 學校的入口網站頁（就是每次連上網常彈出來的歡迎/通知廣告頁）會直接用你的系統瀏覽器打開喔 ✨。", "A25": "🛡️ 咱們不在小巧的 App 裡面硬塞網頁載入器，這樣能徹底避免網頁渲染崩潰，讓軟體永遠輕快穩定 🍃✨！", "A26": "🚀 在瀏覽器中打開看看", "A27": "📭 暫時還沒收集到入口網站位址呢", "A28": "💡 先成功連線一次校園網（或者讓程式被學校的未認證入口網站攔截一次 🚧），小幫手就會自動把入口網站位址記在小本本上啦 📝✨！", "A29": "📋 複製「關閉系統自動彈窗」的魔法指令 🪄", "B101": "😴 還沒連上網呢", "B102": "🚶‍♂️ 現在處於「沒刷卡認證」的狀態，就像你人已經走進吉大校門了，但還沒在閘機上刷校園卡一樣 🪪。", "B103": "👇 輕輕點一下下面的「連線 / 登入」，小幫手就會立刻幫你刷卡放行啦 🚀✨！", "B104": "🏃‍♂️ 正在快馬加鞭連線中…", "B105": "🪪 正在跟學校的閘道器門衛大哥核對你的身份呢，就像門衛大爺瞇著眼看一眼你的校園卡 👀，通常一兩秒鐘就放行啦 ⏱️✨！", "B106": "🎉 已穩穩連線！", "B107": "🛡️ 這條網路通道現在有 JLU Gate 替你寸步不離地守著，放心大膽地去網上衝浪吧 🏄‍♂️💖！", "B108": "🤝 已連線（目前是官方客戶端在當家管事）", "B109": "🏠 官方的 Dr.Com 客戶端正緊緊握著那條認證通道呢（它先一步佔了連接埠），不過好消息是網路完全暢通，你現在可以正常上網噠 🌐✨！", "B110": "🔄 如果想把接力棒交給更輕快的 JLU Gate 來管：先去官方客戶端裡點結束 👋，再回咱們這兒點「連線」就好啦 ✨！", "B111": "🚧 官方客戶端佔著茅坑，但還沒連上網 🙈", "B112": "📞 認證專用的連接埠被官方客戶端死死捏在手裡，偏偏它自己也沒能認證成功——就像有人佔著公共電話亭卻一直沒撥通電話一樣，急死個人 😅💦！", "B113": "👉 快去徹底結束官方的 Dr.Com 客戶端（別忘了檢查選單列和背景叫 DrClientNS 的小尾巴程序喔 🧹），退乾淨後再來點「連線」就能滿血復活啦 🚀！", "B114": "⏳ 正在乖乖等待網路就緒…", "B115": "🚗 電腦現在還沒有可用的網路線連線或 IP 位址呢，就像跑車還沒開上高速公路交流道一樣 🛣️。", "B116": "🔌 把網路線插插緊（或者確認這塊網卡已經拿到了 IP 位址），小幫手一看到路通了就會自動幫你繼續往前衝噠 🏃‍♂️✨！", "B117": "😭 哎呀，沒能連上", "B118": "🧗‍♂️ 小幫手剛才努力嘗試過了，但很遺憾沒能邁過學校閘道器這一關 🚧。", "B119": "👇 別灰心，看看下面貼心列出的原因；順手改好後再點一下「重試」就能過關啦 💪✨！", "B120": "📞 學校官方客戶端搶先佔用了認證專用的「熱線電話號碼」（UDP 61440 連接埠），導致咱們的電話打不進去啦 🙈。", "B121": "🌐 網頁認證需要瀏覽器出馬：登入頁面會在你的瀏覽器裡彈出來，輸完帳號密碼登入成功後，記得回咱們這兒點一下「已完成登入」喔 🙋‍♂️✨！", "B122": "🔄 本機回送（電腦自己跟自己說話 🗣️）", "B123": "🧠 系統核心自帶", "B124": "🏠 127.0.0.1 只在咱們電腦內部自己傳紙條用，資料封包永遠不會順著網路線跑出去的 🔒。", "B125": "🪄 由 VPN 或代理軟體變出來的（目前沒抓到具體是哪個軟體程序在管 🕵️‍♂️）", "B126": "🪄 由「{…}」一手建立", "B127": "🚇 虛擬網卡（加密隧道）", "B128": "🚪 代理軟體把它當成流量出門的總大門；萬一它不小心把校園網段也搶走了，咱們的認證封包就會迷路到不了學校閘道器喔 🚨！", "B129": "🍎 Apple 內部神秘介面", "B130": "⚙️ 蘋果系統 / 晶片組自帶（不是咱們能用手插拔的實體網卡喔 🙅‍♂️）", "B131": "📱 專門用來給蘋果系統內部說悄悄話的（比如跟你的 iPhone 隔空互聯、解鎖之類 ✨），跟咱們連校園網衝浪沒啥關係哈 🏖️。", "B132": "✈️ AirDrop / AirPlay 隔空直連通道", "B133": "📡 蘋果系統專用（無線點對點直連，不是用來上網的口喔）", "B134": "🤝 只負責和附近的 iPad、iPhone 等蘋果全家桶傳照片投影，不挑上網流量的大樑 ✨。", "B135": "⚡ Thunderbolt 橋接", "B136": "🔗 系統自動建立的（當你用 Thunderbolt 線把兩台 Mac 直接連在一起傳檔案時才用得上 💻⚡💻）", "B137": "💤 平時根本用不到它；如果哪天發現它居然被當成了預設上網出口，那說明系統的網路設定順序肯定亂套啦 😵‍💫！", "B138": "📡 Wi-Fi（無線區域網路）", "B139": "💻 電腦內建的無線網卡（或者是把有線轉成無線的隨身轉接器 ✨）", "B140": "🌐 連 JLU.WIFI 時走這個口做網頁認證；連 JLU.PC 時也是靠它來跑 Dr.Com 認證協定噠 🏃‍♂️✨！", "B141": "🔌 USB 外接有線網卡", "B142": "轉接頭 / 擴充座上的外接 USB 網卡（注意：換個 USB 插口它就可能改名字 🎭，所以咱們全靠 MAC 位址來認準它 🎯！）", "B143": "⚠️ 目前還沒有 IPv4 位址呢：多半是因為這根網卡剛插上去，還沒來得及去系統設定裡給它配好靜態固定位址 📝。", "B144": "💡 換插口或者換新網卡後，系統裡的介面名往往會變；但學校只認登記的 MAC 位址，所以一定要核對好 MAC 喔 🪪✨！", "B145": "⚡ 雷靂 / Thunderbolt 有線網卡", "B146": "🔌 內建或外接的高速有線網卡", "B147": "⚡ 雷靂 / Thunderbolt 高階擴充座上的有線網路埠", "B148": "💻 系統內建或者擴充座自帶的有線網路埠", "B149": "⚠️ 目前還沒有 IPv4 位址喔：先把網路線插穩當，或者去給它配好學校分的靜態位址，咱們才能開始認證呀 🛠️✨！", "B150": "📌 插網路線衝浪時就靠它啦：記住填進去的 IP / 遮罩 / 閘道器必須和學校開戶通知單上分給你的一模一樣喔 📋✨！", "B151": "🔌 有線網卡", "B152": "🌐 系統標準網路介面", "B153": "✅ 狀態棒棒噠，隨時可以用於校園網認證 🚀！", "B154": "🧩 其他系統介面", "B155": "⚙️ 系統底層自帶", "B156": "🍃 和咱們平時上網衝浪完全無關，直接無視它就好啦 😎。", "B157": "🔒 已乖乖聽話，鎖定使用「{…}」出戰 🎯！", "B158": "🤖 你還沒填登記的 MAC 位址呢：小幫手會在所有網卡裡聰明地幫你挑一塊最合適的（優先挑穩當的有線網卡喔 🔌✨）。", "B159": "😱 找遍了全身，也沒有哪塊網卡的 MAC 等於你在學校登記的 {…}（電腦裡現有的網卡是：{…}）。快換回當初登記過的那塊網卡/擴充座，或者去學校自助平台改一下登記的 MAC 吧 🏫✍️！", "B160": "🎯 耶！已按 MAC 位址精準鎖定目標網卡：{…}（{…}）✨！", "B161": "👯‍♂️ 咦？發現有多塊網卡的 MAC 位址都長成登記的 {…} 這樣呢！為了防止選錯，建議你在下面手動點名指定其中一塊喔 👇✨。", "B201": "🙈 哎呀，{…} 看起來不是一個合法的 IPv4 位址呢（應該是四段數字加三個點喔 🔢）", "B202": "📏 子網路遮罩的二進位不連續喔：{…}（正常一般都是 255.255.255.0 這樣噠 ✨）", "B203": "🚧 閘道器 {…} 迷路啦，它不在你填的 {…}/{…} 這個網段社區裡面喔 🏘️！", "B204": "👯‍♂️ 閘道器位址可不能和咱們本機的 IP 一模一樣呀（{…}），不然自己發給自己可出不去門喔 🚪💦！", "B205": "🪪 MAC 位址的格式不太對勁呢：{…}（應該是 6 組兩位十六進位字元，比如 a1:b2:c3:d4:e5:f6✨）", "B206": "🚪 閘道器", "B207": "🙈 讀不到這塊網卡是怎麼設定的；請拿出學校的開戶通知單手動照抄固定位址吧 📝，千萬別直接用 DHCP 自動分到的臨時位址喔 🙅‍♂️！", "B208": "⚠️ 這塊網卡現在處於 {…} 模式，身上的位址是自動領到的臨時號碼牌，不能當成固定靜態參數來用喔 🙅‍♂️。請手動照抄學校通知單上的位址吧 ✍️！", "B209": "🤔 系統裡雖然設成了手動設定，但這塊網卡身上目前還空空如也、沒有 IPv4 位址呢 📭。", "B210": "🎉 太棒了！這塊網卡目前就是手動設定模式，下面讀出來的數字就是電腦實際正在用的靜態參數，可以直接拿來用喔（當然，順眼和學校通知單核對一下就更穩妥啦 👀✨）！", "B211": "✍️ 請輸入你學校信箱 @{…} 前面的那一段前綴吧 ✨。", "B212": "🔤 帳號裡面只能有英文字母和數字喔（只要填信箱 @ 前面的前綴就行，別把整個信箱位址都搬進來哈 🙅‍♂️✨）。", "B213": "👨‍🏫 哇，看起來是老師的帳號呢：格式是姓名全拼（比如 zhangshanwu）。遇到同名同姓時學校會在後面加數字後綴，以您的實際信箱前綴為準喔 📧。注意：這裡的密碼填的是您的統一身份認證密碼喔 🔑✨！", "B214": "🎓 同學你好呀！學生帳號的規律是 ＝ 姓氏全拼 ＋ 名字每個字的首字母 ＋ 4 位數字（2 位專業代碼 ＋ 2 位入學年份），舉個栗子：zhangcyy2122 🌰✨。", "B215": "🎒 識別成功！學生帳號：專業代碼 {…}，20{…} 年入學的小可愛/老學長 🎉！記住：這裡填的密碼是你的統一身份認證密碼喔 🔑✨！", "B216": "💡 敲黑板！帳號就是你學校信箱 @{…} 前面的那串前綴，而密碼則是大家最常用的統一身份認證密碼喔 🔑： · 🎓 學生同學：姓全拼 + 名各字首字母 + 4 位數字（專業代碼 2 位 + 入學年份 2 位），比如 zhangcyy2122； · 👨‍🏫 教職員工：姓名全拼，比如 zhangshanwu（同名時學校會加後綴，以信箱實際前綴為準 ✨）。", "B301": "🍃 純淨直連（沒有任何代理接管）", "B302": "🦸‍♂️ 代理已接管公網流量（不過校內網段依然乖乖走直連 🛣️✨）", "B303": "🌍 全域代理模式（連校園網段也被代理一鍋端接管啦 🚨）", "B304": "🚇 TUN 虛擬網卡已開啟，但還沒出手接管預設路由 💤", "B305": "🤔 霧裡看花，暫時無法判斷", "B306": "⚪ 還未設定", "B307": "⚖️ 設定模式（按規則聰明分流 ✨）", "B308": "🌍 代理模式（全域統統走代理）", "B309": "🛣️ 直連模式", "B310": "🎬 目前場景", "B311": "（🕵️‍♂️ 實際探測到：{…}）", "B312": "🍃 所有網路流量都原汁原味地從實體網卡出門{…}，你的校園網認證封包絕對不會被代理軟體誤吞掉，超穩當 🛡️✨！", "B313": "⚖️ 去往外面公網的流量已經由代理軟體接管護送 ✈️，而咱們吉大校內網段的流量依然老老實實從 {…} 直接出門{…}，分工超明確 🤝✨！", "B314": "💡 冷知識時間：像 Shadowrocket（小火箭）或 Clash 這類聰明的軟體，哪怕你表面上切到了「全域（Global）」模式，它們底層通常也會貼心地放行區域網路和校內網段 🛣️，", "B315": "所以光查路由表是分不出你點的到底是「全域」還是「規則」噠——不過不管白貓黑貓，只要咱們的認證封包沒被迫繞遠路，那就是大好事一樁 🎉✨！", "B316": "🚨 哎呀，連咱們學校的內部網段也被虛擬網卡一併接管拿走啦{…}！這意味著你的認證封包得先去代理軟體肚子裡繞一圈才能出來🌀——至於能不能認證成功，全看這段繞路穩不穩當：", "B317": "⏱️ 如果代理軟體手腳麻利、延遲極低還不掉封包，那照樣能蒙混過關認證成功 ✌️；可一旦代理稍微卡頓抖動或者排隊，認證和保活心跳封包一逾時，就會被學校伺服器無情判定為斷線中斷喔 😭💦！", "B318": "🚇 系統裡雖然看到了 TUN 虛擬網卡，但它還沒把預設路由的方向盤搶過去{…}；可能是你的分流規則沒匹配上，或者代理開關其實還沒真正生效呢 🤔。", "B319": "🙈 沒能拿到系統的路由表資訊，這次沒法幫你判斷啦 🤷‍♂️。", "B320": "👍 目前狀態棒棒噠，啥都不用改！如果你想掛著代理去看看外面的世界 🌍，隨時可以在小火箭/Clash 裡切到「設定（規則）」或「代理（全域）」模式喔 ✨。", "B321": "💖 這個分流狀態對校園網認證最友好啦：保持原樣完全不用改！萬一哪天突然莫名其妙斷線，再來確認一下是不是代理規則不小心把 10.0.0.0/8 也給吞掉就行啦 🕵️‍♂️✨。", "B322": "🛠️ 在全域模式下，建議先去點一下「測認證通道延遲」⏱️：如果發現走代理比直連慢了一大截、或者出現了掉封包 🐢，那就快把代理切成「設定（規則）」模式，並手動加一條規則把 10.0.0.0/8 設為直連吧（比如 Clash 寫 IP-CIDR,10.0.0.0/8,DIRECT）✍️！當然，如果測出來延遲依然飛快，那繼續開著全域也能湊合用，只是平時會稍微容易斷線一點點喔 🤏✨。", "B323": "🤔 如果你本意是想走代理上網的，快去檢查下小火箭/Clash 的「設定」開關有沒有真正打開、分流規則有沒有寫對；如果你只是想安安靜靜連個校園網，那現在這樣就挺好噠 🍃✨！", "B324": "🔄 請移步到「網路詳情」頁面，點一下重新檢測看看吧 🔍✨！", "B325": "📖💥 網域解析失敗（找不到網址對應的門牌號碼 🙈）", "B326": "🔌💥 連不上目標伺服器（敲門沒人應 🚪）", "B327": "🔒💥 TLS 加密交握被無情拒絕", "B328": "🙅‍♂️ 伺服器擺手拒絕了咱們的請求", "B329": "⏱️ 等得花兒都謝了，逾時取消 🥀", "B330": "🏫 僅限校內網訪問", "B331": "🌍 校內校外都能隨時開", "B332": "🟢 暢通無阻（HTTP {…}）🎉", "B333": "🟠 伺服器回了個狀態碼 {…} 🤔", "B334": "🔴 伺服器冷酷拒絕", "B335": "🔌 網卡身上還沒有可用的 IP 位址呢，效果就跟沒插網路線一模一樣 🙈。", "B336": "👉 快檢查下網路線插緊了沒，或者去系統設定裡確認這塊網卡已經穩穩拿到了 IP 位址吧 🛠️✨！", "B337": "⚪ 目前還沒有檢測結果喔 🐣。", "B338": "👆 點一下「開始排查」讓小幫手幫你看看吧 🩺✨！", "B339": "🎉 哇喔！測試的所有站點全都一路綠燈暢通無阻，你的網路健康得不得了 🏄‍♂️💖！", "B340": "🏖️ 完美狀態，啥都不用處理，安心衝浪吧 ✨！", "B341": "🤔 發現有網站打不開，而且連咱們學校的認證伺服器（10.100.61.3）都叫不應沒回執——看來問題多半出在咱們校內網這一段路喔 🏫💦。", "B342": "👉 先確認你現在是不是真的連著校園網（插著網路線或連著 JLU.PC），或者喝口水稍等片刻再試 🍵；如果好半天都這樣，那八成是學校網路中心的認證伺服器正在維護打盹呢 😴🛠️。", "B343": "📖 絕大多數打不開的網站都齊刷刷卡在了「網域解析（DNS）」這一步：也就是網址沒能被成功翻譯成 IP 數字位址 🙈💦。", "B344": "💡 試試去把系統的 DNS 換成公共 DNS（比如阿里的 223.5.5.5）吧 🛠️；如果你開著代理軟體，也順手檢查一下它的 DNS 設定，看看是不是不小心把解析請求打回不通的本機路線啦 🕵️‍♂️✨！", "B345": "🔒 能順著網路線摸到伺服器大門，但在進行 TLS 加密交握對暗號時被拒絕了——說明半路上有網路設備在攔截，或者是網站的安全憑證不對勁 🚧🧐。", "B346": "👉 如果你正開著代理軟體，先把它關掉試一次 📴；要是關了代理還是握不上爪，那多半就是外面的網路電信商或防火牆在半路攔截啦 🛡️💦。", "B347": "🤝 網路連線和加密交握全都順利通過啦！只是對面的網站伺服器自己鬧脾氣，給你回了個拒絕狀態碼（4xx / 5xx）😤。", "B348": "☕ 這種通常是對面網站自己在抽風維護或者限流，跟你這台電腦和代理設定都沒關係，換個時間再去逛逛就好啦 🏖️✨！", "B349": "🐼 國內網站刷得飛起，但國外網站全軍覆沒：檢測到你的代理軟體明明在跑，但它的出口節點好像沒能把流量真正帶出國門喔 ✈️💥。", "B350": "👉 快去代理軟體裡換個生龍活虎的節點試試 🔄，或者看看是不是機場套餐流量用光啦 💸；當然也可以先關掉代理，安心享受校內直連的高速衝浪 🏄‍♂️✨！", "B351": "🐼 國內網站一路綠燈，國外網站全都打不開，而且檢測到你壓根沒開代理軟體——哈哈，這就是最標準的「沒開代理」狀態啦 😂✨！", "B352": "💡 當你需要去逛 GitHub 等境外網站時，記得打開你的代理軟體喔 ✈️；如果只是在國內和校內衝浪，現在這樣就完全不用管啦 🏖️！", "B353": "🌍 外面的公網網站都能正常逛，偏偏吉大校內系統（{…}）進不去——因為它們是害羞的「僅限校內網」系統呀 🔒（註：學生信箱本來就是校內外都能開的，所以信箱能開可不算數喔 ✉️😜）！", "B354": "🌉 如果你現在人在校外（比如連著家裡 Wi-Fi 或手機熱點），請先登入學校的 WebVPN 再去訪問它們；如果你明明就在寢室校園網裡，那就先確認一下是不是校園網認證斷線啦 🔄✨！", "B355": "💥 好幾個網站連最基礎的 TCP 連線都建立失敗：說明往外走的出口這一段路直接斷掉啦（可能是代理節點掛了，或者上游網路拔線了 🔌💦）。", "B356": "👉 先在代理軟體裡換個其他節點試試 🔄；要是換了還不行，乾脆先把代理關掉，用純淨直連試試看咱們校園網本身是不是正常的 🕵️‍♂️✨。", "B357": "🔍 順手確認一下校園網是不是已經成功認證在線；也可以去「詳情」頁裡先 Ping 一下閘道器看看路通不通喔 🏓✨。", "B358": "🤔 有零星幾個網站打不開，但它們失敗的原因五花八門，沒有集中在同一個環節上 🧩。", "B359": "👇 咱們可以低頭看看下面每個網站具體卡在哪一步，再來對症下藥，決定是去查 DNS、換代理節點，還是單純怪那個網站自己抽風吧 🩺✨！", "B401": "📭 尚未登記", "B402": "❓ 神秘未知", "B403": "🪪 敲黑板！學校閘道器是個認死理的「認卡不認人」主兒（按 MAC 位址識別設備）：你目前這塊網卡{…} 的實體位址是 {…}，但你帳號檔案裡登記造冊的卻是 {…} 喔 🙈！ 要知道，插網路線走的是有線/USB 網卡的 MAC，而連 JLU.PC 走的則是電腦內建 Wi-Fi 網卡的 MAC——這倆可不是同一塊硬體，也不能互相冒充 🙅‍♂️。 如果你想改用現在這個網路衝浪，得先去學校自助平台把登記的 MAC 修改成 {…} 才行喔 ✍️（友情提醒：改完之後，原來綁定的那塊網卡就暫時不能用來認證啦 🔄）！", "B404": "（🙈 讀不到硬體實體位址呢）", "B405": "（📭 還沒填登記位址）", "B406": "🎭 抓到一隻偽裝者！蘋果系統現在給這塊網卡披上了一層「私人/隨機 MAC」馬甲：{…}（只要看第一組第二個字元是 2 / 6 / a / e，就屬於系統瞎編的隨機位址 🕵️‍♂️）， 而這塊網卡真正的出廠真身位址其實是 {…}，你在學校檔案裡登記的則是 {…}。 別慌，咱們有三種錦囊妙計可以搞定它 💡： 1️⃣ 最推薦 🌟：去蘋果「系統設定 ⚙️ → 網路 → 點這塊網卡 → 詳細資訊 → 硬體 / Wi-Fi」裡，把「私人 Wi-Fi 位址 / 隨機硬體位址」關掉，讓它恢復出廠真身； 2️⃣ 懶人魔法 🪄：直接在咱們 App 的設定裡打開「用登記的 MAC 認證」開關（發給學校的認證信件裡會自動填上登記值，同時不去動系統網卡本身 ✨）； 3️⃣ 下下策 🙅‍♂️：去 ip.jlu.edu.cn 自助平台把學校登記的 MAC 改成目前這個隨機位址（極其不推薦！因為哪天重連或者換個網，系統一高興又會再換個新的隨機位址，到時候又得斷網啦 😭）。", "B407": "📡 注意啦！連 JLU.PC 無線網時，必須使用這台電腦內建 Wi-Fi 網卡的 MAC 位址來認證喔。如果你之前在學校平台登記的是外接 USB 網卡或插網路線網路埠的 MAC， 在這兒認證是一定會碰壁失敗的 🚧——你需要先去 ip.jlu.edu.cn 自助平台，把登記的 MAC 改成現在這塊 Wi-Fi 網卡的位址才行喔 ✍️（注意：改完之後，原來插網路線的那個口就會失去認證資格啦 🔄）！", "B408": "🎉 連上 JLU.PC 後，系統常常會自動跳出一個 login.jlu.edu.cn 的歡迎網頁，這是咱們校園網的入口引導頁（完全屬於正常現象哈 🤗）。 你直接隨手把它關掉就行 ✖️：因為核心的認證工作已經由咱們 JLU Gate 在背景悄無聲息地搞定啦 🛡️，千萬不需要在那個網頁裡再去下載老舊的官方客戶端囉 🙅‍♂️✨！", "B409": "🙅‍♂️ 學校伺服器搖了搖頭，覺得目前這個 MAC 位址不屬於你的帳號檔案呢。蘋果 Mac 電腦的硬體 MAC 是出廠就焊死在網卡裡的，沒法靠軟體隨便改掉 🛠️： 請去 ip.jlu.edu.cn 自助平台核對或修改一下登記的 MAC 位址 ✍️，或者把你當初登記過的那個 USB 網卡/擴充座重新插回來吧 🔌✨！", "B410": "📱 JLU.WIFI 規定同一個帳號最多只能同時讓 {…} 台設備在線衝浪 🏄‍♂️。一旦有新設備登入擠進來，就會像排隊買奶茶一樣，把最早登入進來的那台老設備給無情踢下線 🦵💥！ 你剛才的在線工作階段，很可能就是這麼被你自己的另一台手機或平板給擠掉的喔 🙈✨。", "B411": "🔄 如果你現在點重新登入，就會把這台電腦重新排到在線佇列的最末尾，同時順腳踢掉目前佇列裡排在最前面的那台舊設備 🦵——如果那恰好是你正在看劇的平板或手機，它可就要瞬間斷網囉 📱💦！", "B412": "💻 本機提示：在 {…} 台設備的名額上限之外，現在點擊登入會讓你重新排到隊尾接管網路喔 🔄。 {…}", "B413": "💡 小科普：每次剛連上新 Wi-Fi 時自動彈出來的那個小網頁視窗，其實是蘋果 macOS 系統自帶的「強制入口網站助手（Captive Network Assistant）」🤖，是由系統底層直接觸發的，咱們 App 也沒法半路攔截它 🤷‍♂️。 不過別管它！只要咱們的程式在背景飛快地幫你完成了認證 ⚡，那個小視窗察覺到網通了，自己就會識趣地乖乖關掉啦 👋✨！", "B501": "⚪ 還沒檢測過呢", "B502": "✍️ 剛剛手動輸入的", "B503": "💖 已妥善儲存（而且之前成功登入過喔 ✌️）", "B504": "🤔 已儲存（但還沒上場驗證過 🐣）", "B505": "😭 已儲存（但上次被伺服器拒絕了 💔）", "B506": "🤖 自動模式（還沒出動探測 🕵️‍♂️）", "B507": "💻 本機 {…}", "B508": "🎉 目前已經在網上衝浪啦（雖然還沒在咱們這兒設定帳號 🏄‍♂️）", "B509": "🛡️ 為了防止連環報錯，不再自動使用舊密碼，這就帶你去重新輸入一次 ✍️", "B510": "🔑 為了避免用錯密碼被伺服器拉黑，請重新輸入一次正確的密碼吧 ✨！", "B511": "🙈 填的伺服器位址格式不太合法喔", "B512": "🚀 已經用上次貼心記在小本本上的入口網站位址幫你打開啦 📖✨！", "B513": "🕵️‍♂️ 正在努力嗅探入口網站位址中… ⏳", "B514": "🚀 小火箭 / Clash 等代理", "B515": "🚪 經由預設總出口", "B516": "🔌 哎呀，有線網卡 {…} 身上還沒有 IP 位址呢 📭。快把學校通知單上分的靜態參數填進來（或者去系統設定裡把網卡改成 DHCP 自動取得），咱們再來連線吧 🛠️✨！", "C01": "🙋‍♂️ 這裡需要你搭把手處理一下；搞定後點「重試」就能繼續衝浪啦 🏄‍♂️✨！", "C02": "🔄 重試一下", "C03": "📊 看看網路詳情", "C04": "✖️ 關閉", "D01": "📊 網路詳情大透視", "D02": "🔄 重新整理一下", "D03": "⏳ 正在努力讀取中…", "D04": "🦸‍♂️ VPN/TUN 已接管流量", "D05": "🍃 VPN/TUN 未接管", "D06": "· ⚠️ DNS 被代理悄悄劫持啦", "D07": "🚀 代理模式（對照小火箭/Clash 等）", "D08": "✅ 和你設定的選擇完全一致喔！", "D09": "🤔 咦，和你在軟體裡選的好像不太一樣呢", "D10": "🕵️‍♂️ 正在仔細判斷中…", "D11": "👉 你在代理軟體裡選的是：", "D12": "🍃 沒發現 utun 虛擬介面：說明目前沒有代理或 VPN 在搶方向盤（路由）喔 🚗✨。", "D13": "🚪 預設總出口", "D14": "🪪 認證流量專屬出口", "D15": "🔌 有線網路埠", "D16": "📡 無線 Wi-Fi", "D17": "🪪 認證流量", "D18": "🟢 已啟用", "D19": "⚪ 未啟用", "D20": "🏭 出廠真身 MAC {…} ← 認證實際用的是這個喔（雖然系統現在披著私有/隨機位址的馬甲 🎭）", "D21": "🔗 鏈路本地位址 {…}", "D22": "🙈 沒找到實體有線網路埠呢", "D23": "🧭 路由與 DNS 指路牌", "D24": "🛣️ 預設路由", "D25": "{…}（下一跳閘道器 {…} 🦘）", "D26": "📖 系統 DNS", "D27": "（🙈 讀不到呢）", "D28": "💡 系統目前的 DNS 是 198.18.x.x（這是代理軟體產生的 fake-ip 假位址 🎭）。不過別擔心，咱們程式的探針不走它，會自己直接發 UDP 查詢噠 🚀！", "D29": "⏱️ 認證通道延遲（UDP 61440 來回跑一圈 🏃‍♂️）", "D30": "💡 開著全域代理到底能不能穩穩認證，全看這條小路通不通暢——光看模式名字可不準喔 🧐！咱們用直連和走代理分別實測 3 次真實的 challenge 封包看看 🎯：", "D31": "⏳ 正在掐錶測量中…", "D32": "🏃‍♂️ 測測認證通道", "D33": "🏓 Ping 測試（TCP 交握延遲）", "D34": "👇 點下面的「開始 Ping」測一測去閘道器和公網來回要多久；還能順便對比一下走 VPN 會多花多少時間喔 ⏱️✨！", "D35": "🏓 開始 Ping！", "D36": "🚀 飆車測速（HTTP 下載，直連 vs VPN 大比拼 🏎️）", "D37": "咱們會分別用「網路埠直連」和「目前預設出口（含 VPN）」各下載一小段資料比比速度 🏁，單位是 Mbps 喔 ✨。", "D38": "⚠️ 網路埠直連測速暫不可用：可能是被校園閘道器攔住了 🚧，或者這個測速點只歡迎代理流量通過喔 🤔。", "D39": "🏎️ 正在全力測速中…💨", "D40": "🚀 開始測速", "D41": "📋 複製全部資訊", "D42": "✖️ 關閉", "E01": "📦💥 認證封包格式不對勁（{…}）", "E02": "👽 收到了一封看不懂的神秘封包：類型 0x{…} 子類型 0x{…}，長度 {…}", "E03": "📏 {…} 寫得太長啦，最多只能裝下 {…} 個位元組喔 🙈", "E04": "📭 尚未登記 MAC", "E05": "🪪💥 網卡 MAC 位址對不上號：你在學校檔案裡登記的是 {…}，但目前出戰的介面卻是 {…} 🙈。如果換了新的 USB 網卡或擴充座，一定要先去學校自助平台把新 MAC 登記上去才能用喔 🏫✍️！", "E06": "📭 介面 {…} 身上空空如也，還沒有 IPv4 位址呢。請先去蘋果「系統設定 → 網路」裡給這塊網卡配好學校分的固定靜態位址吧（記住：靜態認證可不接受 DHCP 自動分的位址喔 🙅‍♂️✨）！", "E07": "🔌💔 網卡 {…} 突然中斷連線啦（是不是網路線鬆了或者不小心拔掉了擴充座呀 🤔？）。把它重新插緊後，小幫手會自動幫你秒重連噠 🔄💖！", "E08": "⚠️ 介面 {…} 目前還在偷懶使用 DHCP 自動取得位址，還沒改成手動設定呢 🛠️。學校的靜態認證規矩嚴，不接受 DHCP 臨時位址喔，快去改一下吧 ✍️！", "E09": "🧐 {…} 和檔案裡記的不一致喔：按理說應該是 {…}，但現在檢測到的是 {…} 💦", "E10": "😴 呼叫學校認證伺服器 {…} 完全沒反應（無回應）。請先檢查一下網路線插好了沒、靜態 IP 和閘道器有沒有抄錯吧 🔍🔌！", "E11": "🚨 抓到代理軟體把咱們校園網段也給接管搶走啦（目前出口是 {…}）🕳️！這會讓認證封包迷路的，快去代理軟體的分流規則裡把 10.0.0.0/8 設為直連（DIRECT），或者先把全域路由關掉吧 🛠️✨！", "E12": "🤝 官方的 Dr.Com 客戶端{…}正緊緊握著認證通道呢（它搶先一步佔用了本機 61440 連接埠）——不過這通常說明它已經在盡職盡責地替你連上網啦 🌐✨！", "E13": "🔄 如果你想換咱們更輕快好用的 JLU Gate 來接管網路：先去官方客戶端裡面點登出 👋；要是退了之後連接埠還被霸佔著，就去活動監視器裡把它的背景小尾巴程序 DrClientNS 徹底關掉就行啦 🧹✨！", "E14": "📞💥 哎呀，校園網認證專用的那個「熱線電話分機號」（本機 UDP 61440 連接埠）已經被別的程式捷足先登佔走啦{…} 🙈！", "E15": "💡 十有八九是學校官方的 Dr.Com 客戶端幹的，先把它徹底退出去，咱們就能順利接管啦 🚀✨！", "E16": "🏞️ 檢測發現目前連的網路好像不是吉大校園網喔（{…}），小幫手先乖乖待命啦 💤", "E17": "🛠️ 哎呀，這種接入方式咱們目前還沒學會支援呢：{…} 🙈", "E18": "⏱️💔 等得花兒都謝了，學校伺服器還是沒回信（回應逾時：{…}）🥀", "E19": "🚧 網路通道出現了一點小異常：{…} 💦", "E20": "🛑 操作已取消", "E21": "🔄 學校伺服端喊話：這次要求必須用 DHCP 動態取得位址喔！", "E22": "🪪💥 MAC 位址校驗沒通過", "E23": "🥵 學校伺服器現在太忙啦，忙得滿頭大汗", "E24": "🔑💥 密碼不對喔", "E25": "💸 網費餘額不足啦", "E26": "🥶 糟糕，帳號被凍結停機了", "E27": "🏠💥 IP 位址對不上號（不匹配）", "E28": "🪪💥 MAC 位址對不上號（不匹配）", "E29": "📱💥 同時在線的設備數量超標啦", "E30": "🙅‍♂️ 伺服器拒絕了你的登入憑證（錯誤碼 0x15）", "E31": "💥 IP 位址和 MAC 位址全都對不上號！", "E32": "🔄 必須使用 DHCP 動態位址", "E33": "🪪 目前這台電腦出戰的網卡，和你帳號綁定的那塊不一樣喔：請確認你插的是當初在學校登記過的那塊網卡（而且沒有開啟系統的隨機/私人 MAC 偽裝 🎭）！", "E34": "🥵 學校認證伺服器現在排隊的人太多、有點過載喘不過氣啦！完全不用改任何設定，咱們喝口水稍等片刻 🍵，小幫手會自動幫你重試噠 🔄✨！", "E35": "🔑 快核對一下你的校園網（統一身份認證）密碼是不是輸錯啦；如果你前兩天剛在網頁上改過新密碼，記得在咱們這兒也同步更新一下喔 ✍️✨！", "E36": "💸 你的校園網帳戶餘額見底啦！快去自助平台充點網費，餵飽它就能立刻恢復衝浪囉 💰🏄‍♂️！", "E37": "🥶 你的校園網帳號目前處於停機或凍結狀態呢，這得聯繫學校的大數據和網路管理中心老師幫忙解凍喔 📞🏫。", "E38": "🏠 這台電腦現在的 IP 位址和你帳號綁定的固定 IP 不符喔：快檢查一下網路線是不是插錯了寢室牆上的連接埠 🔌，或者是不是該改成自動取得 IP 呀 🤔？", "E39": "📱 你帳號名下同時在線的設備數量已經頂到天花板上限啦！先去其他手機或電腦上登出退出一台，就能把名額騰出來囉 🔄✨。", "E40": "💡 在咱們吉大校園網裡，報這個 0x15 錯誤碼通常都是因為「密碼填錯了」🔑（開源社群的 jlu-drcom-ng 前輩們在程式碼裡也是這麼標註噠 🤓）；", "E41": "當然也有極小機率是學校伺服端升級改了脾氣。建議你先去網頁版統一身份認證試登一下確認密碼沒錯 🌐，再回咱們客戶端裡重新輸入一次吧 ✍️✨！", "E42": "👉 請去蘋果「系統設定 → 網路」裡，把這塊網卡的設定方式改成「使用 DHCP（自動取得位址）」，然後再回來點重試就好啦 🔄✨！", "G01": "🎉 選 JLU.WIFI 的同學看過來：不用填 IP 和 MAC 喔！", "G02": "🤔 看著參數一臉懵？走，去校園網自助平台查一查 🔍！", "G03": "它是超省心的網頁認證 🌐，位址由 DHCP 自動分發；只要用「統一身份認證」的帳號密碼在彈出的網頁裡登一下就好啦 🥳！", "G04": "⚠️ 連之前先瞪大眼睛看清楚 Wi-Fi 名字是不是 JLU.WIFI（大寫字母、中間帶個點 🟢），千萬別在名字很像的野雞網路裡輸帳號呀 🛡️！", "G05": "💡 固定 IP 和閘道器藏在「查詢信息」裡；登記 MAC 則在「變更 MAC」裡。要是死活連不上，也有可能是網費餘額告急啦 💸！", "G06": "🌐 傳送門：打開 ip.jlu.edu.cn/pay 🚀", "G07": "🔼 收起小卡片", "G08": "📖 看看詳細步驟", "G09": "1️⃣ 先連上 JLU.WIFI（名字要一字不差喔），然後點選單列上的小圖示 → 點「登入」🚀，", "G10": "2️⃣ 在跳出來的網頁裡，填上你「統一身份認證」的帳號和密碼就搞定啦 ✌️✨！", "G11": "🎈 完全不用填 IP / 遮罩 / 閘道器 / MAC——位址都是自動發的，網頁認證只認你的帳號不認人 😎！", "G12": "🏫 自助平台平時主要是用來查查網費 💰、辦個開戶 📝、或者看看有哪些設備在線的 👀。", "G13": "🔑 登入它要用：校園卡號（就是錄取通知書上那串長數字，比如 20220501324）＋ 6 位數字密碼 ＋ 驗證碼 🔢✨。", "G14": "🔍 進去後點「查詢信息」：你的 IP、閘道器、DNS 全都在這兒排排坐呢——不過這裡沒有 MAC 位址喔 🙅‍♂️。", "G15": "🪪 想看或修改登記的 MAC？得走旁邊另一個門：點「變更 MAC」進去就能看到或修改啦 ✍️✨！", "G16": "😮 如果列表裡空空如也、沒有你的 IP：先退回主選單點「網絡開戶」🎉，開通成功後再回來查就有啦！", "G17": "🤯 傻傻分不清的「三種密碼」大揭秘！", "G18": "💻 怎麼找自己電腦的 MAC 位址？", "G19": "💡 友情提示：如果你其實連的是 JLU.WIFI，那這些靜態參數一個字都不用填！因為它是動態位址的網頁認證哈 🏖️✨。", "G20": "💳 1. 吉大 V 卡（校園卡）", "G21": "帳號 = 錄取通知書編號；密碼 = 6 位純數字 🔢。去校園網自助平台查資訊、交網費用的就是這套喔 💰！", "G22": "📧 2. 吉大信箱", "G23": "擁有獨立的一套密碼 🔒，專門用來登入學校信箱收發信件 ✉️；不過它的帳號前綴和統一帳號是一模一樣的 ✨。", "G24": "🔑 3. 統一身份認證（最常用 🌟）", "G25": "查教務、連 VPN、還有咱們這個 JLU Gate（包括 JLU.WIFI 網頁登入）用的全都是這套王牌帳號密碼 👑✨！", "G26": "🔌 找有線網卡的 MAC：", "G27": "打開蘋果「系統設定」⚙️ → 點「網路」🌐 → 點你插著的那根有線網卡（USB 轉接網卡也在這一欄喔）→ 點「詳細資訊」→ 就能看到「MAC 位址」啦 👀✨！", "G28": "📡 找 Wi-Fi 的 MAC：打開「系統設定」⚙️ → 點「Wi-Fi」→ 點已經連上的校園網（JLU.WIFI / JLU.PC）旁邊的「詳細資訊 / ⋯」按鈕 → 就能找到 MAC 啦 🎯！", "G29": "⚠️ 注意咱們要的是這塊網卡出廠自帶的真實實體位址喔！如果系統貼心過頭、預設開了「私人 Wi-Fi 位址 / 隨機 MAC」🎭，", "G30": "記得先把它關掉 🙅‍♂️，或者在咱們 App 的設定裡勾上「用登記的 MAC 認證」也行 🪄✨！", "G31": "💸 怎麼都連不上？摸摸口袋，是不是欠費啦 🙈", "G32": "校園網很寬容的，餘額 -10 元、0 元都還能讓你繼續衝浪 🏄‍♂️；但一旦跌到 -20 元就會無情斷網啦 ✂️（有線 / JLU.PC / JLU.WIFI 統統斷掉喔）。", "G33": "💰 儲值檔位只有 20 / 40 / 100 元三檔，錢會直接從你的校園卡餘額裡扣走——注意啦！如果已經欠了 20 元，只充 20 元進去變成 0 元是不會復機的 😱，", "G34": "必須一口氣充 40 元，讓餘額變成正數的 20 元，網路才會重新向你敞開懷抱喔 🤗✨！", "G35": "🔍 這些餘額和帳單數字都在自助平台的「查詢信息」裡，用你的校園卡號 + 6 位 V 卡密碼就能登進去看啦 👀。", "G36": "🚀 打開自助平台去瞧瞧", "G37": "🌱 萌新必看小貼士 ✨", "G38": "📸 換寢室的時候，學校可能會跳出一個「使用者遷移」頁面：上面寫著網卡的實體位址（MAC）、原本的 IP 和遷移之後的 IP——記得截圖保存下來 📷，之後填網路參數、去自助平台登記 MAC 都要用到。", "M01": "耶！🎉 目前沒有需要處理的網頁認證喔 🏖️✨", "M02": "🔙 溜回去", "M03": "哎呀，這裡需要你搭把手處理一下 🙋‍♂️；搞定後點「重試」就好啦 🔄✨！", "M04": "🌐 小路（鏈路）", "M05": "🏠 本機 IP", "M06": "學校分給咱們這台電腦的專屬門牌號碼 🪧✨", "M07": "🟢 穩穩在線中", "M08": "這期間小幫手一直在背景默默幫你續命認證 💓，完全不用你操心喔 ☕️✨！", "M09": "🚪 出口", "M10": "認證封包從哪張網卡溜出去 🏃‍♂️；走代理伺服器不一定壞事，但如果太慢或掉封包 🐢，會被學校誤判斷線喔 🥺", "M11": "🔌 插網路線的那種，穩如泰山 ⛰️✨！", "M12": "📡 學校的無線訊號，需要用 Wi-Fi 網卡的身份來刷卡認證喔 🪪✨", "M13": "🌐 網頁登入那種，呼叫瀏覽器出馬 🧭✨！", "M14": "🤖 自動模式：先幫你探探路 🕵️‍♂️，再決定走哪條道最順暢 ✨！", "M15": "⏰ {…} 起 · 陪伴你 {…} 啦 ✨", "M16": "✍️ 填好帳號密碼（哪怕斷線也會自動幫你秒重連喔 🔄💓）", "M17": "👋 先撤啦（下線）", "M18": "🚀 衝鴨！登入！", "M19": "🔄 再試一次", "M20": "🔑 重新輸入密碼", "M21": "哎呀，代理伺服器把校園網段也包攬啦 🚧，咱們需要先加一條直連小捷徑 🛣️：", "M22": "📋 複製魔法指令", "M23": "🙋‍♂️ 我跑完指令啦，重新檢測！", "M24": "📱 JLU.WIFI 最多只能同時讓 {…} 台設備在線喔 👯‍♂️", "M25": "🤺 重新把在線名額搶回來！", "M26": "🌐 打開網頁登入頁", "M27": "🛠️ 重新設定一下…", "M28": "🏭 改用出廠自帶 MAC {…} ✨", "M29": "🏫 打開自助平台（去改登記的 MAC ✍️）", "M30": "同一帳號同一時間只能有一台設備在線喔 ☝️。想讓這台電腦上線？去另一台設備上登出一下（或者喝口水等 30 秒自動釋放 🍵），再點重試就好啦 🔄！", "M31": "咦？這個 MAC 已經被別的設備捷足先登啦 😱！如果你換了網卡或用了共用的便宜網卡，快去學校平台核對一下登記資訊吧 🔍🏫！", "M32": "⚙️ 設定", "M33": "🧭 寶藏站點", "M34": "📊 詳情", "M35": "🩺 診斷", "M36": "🏥 健檢", "M37": "🚪 結束", "M38": "🌟 更新：去 GitHub 看看有沒有新鮮出爐的版本 📦", "M39": "🔍 正在努力搜尋最新版本… ⏳", "M40": "哇喔！已經是最新最棒的版本 v{…} 啦 🎉✨！", "M41": "叮咚！🔔 發現新版本 {…} 啦：點一下「更新」就能自動下載並換新裝喔 👗✨！", "M42": "⬆️ 立即更新", "M43": "⏳ 正在瞧瞧…", "M44": "🔄 再查一次唄", "N01": "👋 中斷連線", "N02": "🚀 立即連線", "N03": "🔄 重新整理狀態", "N04": "🏥 網路健檢", "N05": "⚙️ 設定…", "N06": "🚪 結束 JLU Gate", "N07": "📏 螢幕寬度 {…}，中線位置 {…}", "N08": "🧹 撤回位置偏好、恢復預設擺放", "N09": "👈 哎呀，圖示跑到螢幕左半邊去啦", "N10": "💖 關於 JLU Gate", "N11": "🛡️ 默默守護你的校園網時刻在線 ✨", "N12": "🎉 耶！已成功切換到最新版本！", "N13": "👋 舊版本（build {…}）已經功成身退，現在是由嶄新的 build {…} 為你服務喔 🚀✨！", "N14": "🙋‍♂️ JLU Gate 需要你搭把手處理一下喔", "N15": "📦 發現目前的 App 還沒住進系統的 /Applications（應用程式）資料夾裡，沒法自動幫你替換更新呢 🥺。請先把 JLU Gate 拖進「應用程式」資料夾安家，再來體驗絲滑的一鍵更新吧 🏠✨！", "N16": "😭 下載失敗啦：{…}", "N17": "📦💥 解壓縮失敗啦：{…}", "N18": "📥 正在努力下載新版本中… ⏳", "N19": "📦 正在拆包解壓縮中… ✨", "N20": "🤔 咦？下載的壓縮檔裡居然沒找到 .app 程式呢", "N21": "🔄 準備退下舊版本並換上新裝… 👗✨", "N22": "🌟（比現在用的版本更新喔！）", "N23": "🍂（比現在用的版本舊，建議順手刪掉省空間喔 🗑️）", "N24": "⚠️ JLUGate: 寫日誌檔案時絆了一跤 {…}", "N25": "🎒 JLUGate: 隨身攜帶的可攜式副本不註冊開機自啟喔 ✨", "N26": "⚠️ JLUGate: 設定開機自啟登入項目時失敗啦 {…}", "P01": "🩺 這裡健檢的是你平時用瀏覽器上網真正會走的那條路：看看出口 IP 是哪兒、WebRTC 會不會漏底、DNS 有沒有跑偏、還有煩人的人機驗證能不能刷出來 🧩✨。", "P02": "🌐 到底能不能愉快上網（含校內各大系統 🏫）", "P03": "✨ 一進這個頁面小幫手就會自動幫你開始健檢啦；下面的按鈕是留給你隨時複查重試用的 🔄！", "P04": "🏫 校內專屬系統（教務和通知只有校內能開 🔒；信箱則是校內校外都能隨時打開噠 ✉️✨）", "P05": "🩺 正在認真健檢中… ⏳", "P06": "🔄 重新健檢一次", "P07": "🚪 出口 IP", "P08": "🤖 人機驗證（Captcha）", "P09": "（📺 嗶哩嗶哩 B 站聰明地走了另一條分流小路 🛤️）", "P10": "⚠️ 咦，各個檢測源報出來的國家不一樣呢（{…}）：這大機率是個廣播 IP 或者中轉節點喔 📡✨", "P100": "🇯🇵 日本", "P101": "🇰🇷 韓國", "P102": "🇰🇷 南韓", "P103": "🇸🇬 新加坡", "P104": "🇺🇸 美國", "P105": "🇭🇰 香港", "P106": "🇹🇼 台灣", "P107": "🇬🇧 英國", "P108": "🇩🇪 德國", "P109": "🇷🇺 俄羅斯", "P11": "🧭 DNS 與 IP 出口默契度：", "P110": "🇨🇦 加拿大", "P111": "🇦🇺 澳洲", "P112": "🇳🇱 荷蘭", "P113": "🇫🇷 法國", "P114": "🙈 沒能拿到 DNS 的出口位址（可能是 DNS 被代理軟體嚴密接管了，或者乾脆連不上），這次就沒法幫你比對啦 🤷‍♂️。", "P115": "🎭 系統 DNS 目前被代理軟體接管啦（解析出來的出口是 {…} 這個 Fake-IP 假位址），", "P116": "所以咱們看不到它背後真實的實體位置——別擔心，這可不是洩漏或不一致，只是穿了隱身衣比不出來而已喔 🧥✨！", "P117": "🌟 太完美啦！你的 DNS 解析出口和最終的 IP 出口完完全全是同一個位址，在各大網站的風控眼裡看起來就像本地居民一樣自然絲滑 🏡💖！", "P118": "🤔 缺少國家地理位置資訊，暫時還沒法幫你比對呢 🕵️‍♂️。", "P119": "✅ 你的 DNS 出口({…}) 和 IP 出口({…}) 都在同一個國家/地區，步調一致，觸發風控的風險很低喔 👍✨！", "P12": "🏎️ 頻寬速度三檔大比拼", "P120": "🚨 哎呀！你的 DNS 解析是從 {…} 冒出來的，但實際流量的 IP 卻遠在 {…}——倆人隔著十萬八千里呢 🌍💦，", "P121": "這樣「身首異處」最容易被精明的風控系統一眼識破判定為代理異常 👀，有時候甚至比單純用機房 IP 還容易被封號或彈驗證喔 😱！", "P13": "🛣️ 純直連", "P14": "🚪 預設出口（含代理）", "P15": "💻 本機代理連接埠", "P16": "💻 本機代理 127.0.0.1:7890", "P17": "🏎️ 正在飆車測速中… 💨", "P18": "🚀 測速", "P19": "💡 沒找到本機代理連接埠喔：如果你開的是 TUN 全域虛擬網卡模式，那第二檔測出來的就已經是最終速度啦，不用再測第三檔囉 ✌️✨！", "P20": "🎯 已經自動幫你嗅探到代理連接埠 {…}（{…}）啦；要是不對也可以手動改喔 ✍️！", "P21": "🌐 在瀏覽器裡打開校園網入口網站看看", "P22": "🏡 住宅 / 電信商原生 IP：最受 Claude、Netflix 等傲嬌串流媒體和 AI 站點的歡迎啦 💖✨！", "P23": "🏢 機房資料中心 IP：很多警惕性高的網站看到它會直接擺手拒絕 🙅‍♂️，或者瘋狂彈人機驗證考你眼力 🧩💦", "P24": "📱 行動網路 IP：平時表現還不錯 👍，就是偶爾可能會被限速喔 🐢", "P25": "🤔 查到的歸屬資訊太少啦，暫時還判斷不出它是哪種類型的 IP 呢 🕵️‍♂️", "P26": "👆 點上面的「開始檢測」，小幫手就會去幫你打聽這個出口 IP 的戶口名簿和類型（到底是溫馨民宅 🏡 還是大機房 🏢）✨", "P27": "🗣️ 正在挨家挨戶問不同的網站：「嘿，在你眼裡我是從哪兒來的誰呀？」… 🔍", "P28": "👆 點一下「開始檢測」，咱們去問幾個主流網站同一個哲學問題 🧐✨", "P29": "🧼 出口 IP 純淨度大考驗", "P30": "🚨 糟糕，已被公開黑名單標記為代理 IP 啦", "P31": "📍 地理位置", "P32": "🏷️ 歸屬電信商 (ASN)", "P33": "🧬 IP 類型", "P34": "· 🏢 帶有資料中心機房標記", "P35": "🔍 其他旁證線索", "P36": "⚪ 還沒去打聽呢", "P37": "🌍 地區：{…}", "P38": "🏢 接入機房：{…}", "P39": "👀 看看賽博大善人 Cloudflare 覺得你是從哪個國家、哪座機房鑽出來的 🕵️‍♂️", "P40": "💡 Cloudflare 可是全世界最會認「你從哪兒來」的行家之一；連上的機房離你越近，上網衝浪通常就越快越絲滑喔 🏄‍♂️✨！", "P41": "📭 沒收到回執呢（{…}）", "P42": "📡 STUN 是瀏覽器裡的 WebRTC 用來打聽「我真實的公網位址是多少」的悄悄話協定；咱們用一模一樣的方法去試探一次 🕵️‍♂️✨！", "P43": "💡 啥叫「DNS 洩漏」呢？就是你明明以為流量都穿好代理隱身衣了 🧥，結果查網域的活兒還是交給了本地電信商，一下子就暴露行蹤啦 🙈！", "P44": "⚠️ 另外還發現了可疑的 DNS 劫持跡象喔（明明根本不存在的亂碼網域，居然也被強行塞了個 IP 位址回來 👻）！", "P45": "✅ 太棒啦！系統 DNS 和公共 DNS 的出口完全一致（{…}）🎉", "P46": "🤔 系統 DNS 出口在 {…}，但公共 DNS 出口卻在 {…}：倆人分道揚鑣，說明你的網域解析走了兩套不同的路線喔 🛤️！", "P47": "📍 系統 DNS 出口在 {…}；但公共 DNS 聯繫不上（可能是被攔住了 🚧，或者被代理軟體全權接管啦 🦸‍♂️）。", "P48": "📭 系統 DNS 沒回信；不過公共 DNS 的出口在 {…} ✨。", "P49": "😱 兩種 DNS 都沒拿到回執，可能整條 DNS 查詢通道都被攔截或接管啦 🚧！", "P50": "🟢 暢通可用", "P51": "🔴 連不上呢", "P52": "🟡 會跳出人機驗證考你 🧩", "P53": "🟠 網站返回了奇奇怪怪的意外內容 👽", "P54": "🏠 出口就是咱們本機的位址：說明這股流量乖乖走了直連，沒進代理隧道喔 🍃！", "P55": "✈️ 出口國家/地區在 {…}：流量已經坐上代理小飛機，經過異地節點出去啦 🌍✨！", "P56": "🔀 出口位址和咱們本機不一樣喔", "P57": "🛡️ 沒拿到 STUN 回執：說明 UDP 流量可能被嚴嚴實實擋住了（不過別慌，這種情況下 WebRTC 反而絕對不會洩漏真實 IP 喔 ✌️✨）！", "P58": "🚨 哎呀！STUN 一眼就看到了咱們本機的真實位址 {…}：這意味著瀏覽器的 WebRTC 可能會把你的真實 IP 暴露給網站喔 🙈！", "P59": "👀 STUN 看到的位址是 {…}：這就是瀏覽器透過 WebRTC 會向外界展示的面孔 🎭。", "P60": "⚪ 還沒開始檢測呢 🐣", "P61": "😭 全軍覆沒連不上：你去逛境外網站時，那些人機驗證的勾選框很可能會轉圈圈載入不出來喔 🧩💦。", "P62": "😅 有 {…} 個站點一上來就甩給你人機驗證頁：看來你現在用的這條出口線路被風控系統「重點關照」啦 🚨！", "P63": "🎉 全都能絲滑載入！看來你現在的 IP 表現很乖，暫時沒有被風控針對喔 ✌️✨！", "P64": "📊 {…}/{…} 個可用，還有 {…} 個暫時連不上 🤔", "P65": "🔌 網路埠代號（比如 en0 / en7）", "P66": "🏷️ 這是系統給每塊網卡起的內部小名。外接的 USB 網卡只要換個插口，名字就可能變掉 🎭；所以咱們認網卡只認它永恆不變的 MAC 位址，不看這個小名喔 🎯！", "P67": "🪪 MAC 位址（實體位址）", "P68": "🏭 網卡出廠時就烙在晶片上的唯一身分證字號。學校就是靠 MAC 來認你這台設備的——如果你換了新網卡或者換了別人的擴充座 🔄，一定要去學校自助平台重新登記新 MAC，不然閘道器大哥絕對不放行喔 🚧！", "P69": "🏠 IPv4 位址", "P70": "🪧 這台電腦在吉大校園網裡的專屬門牌號碼。因為學校是按每個宿舍的牆上連接埠來分配固定位址的，所以必須老老實實照抄通知單 📝，不能用 DHCP 自動隨便領一個喔 🙅‍♂️！", "P71": "🎭 子網路遮罩", "P72": "📏 用來劃定門牌號碼裡哪一段代表「咱們這棟宿舍樓」、哪一段代表「外面的世界」。要是填錯了，電腦就會把同樓的閘道器當成外人，直接拒絕溝通連不上網啦 🙈！", "P73": "🚪 預設閘道器", "P74": "🦘 資料封包走出咱們宿舍樓的第一跳（也就是樓道路由器）。它必須和你的 IP 在同一個網段裡，不然你喊破喉嚨發出去的封包也沒人接應喔 📣💦！", "P75": "📖 DNS（網域名稱系統）：專門負責把好記的網址（比如 jlu.edu.cn）翻譯成冷冰冰的 IP 數字 🔢。當它被代理軟體接管劫持時，往往會把所有網址都先翻譯成 198.18.x.x 這種臨時假位址 🎭。", "P76": "🔗 鏈路本地位址（169.254.x.x）", "P77": "⛺ 當網卡還沒領到正式 IP 位址時，自己給自己隨便編的一個臨時帳篷位址。Dr.Com 的登入認證封包裡規矩多，也得順手帶上它，沒有的話就填 0 交差 ✨。", "P78": "🧭 路由 / 流量出口", "P79": "🚪 決定資料封包到底從哪塊網卡邁出家門。如果去往學校認證伺服器（10.100.61.3）的出口變成了 utun 開頭的虛擬網卡 🕳️，那就說明認證流量被代理軟體半路截胡啦，大機率到不了學校閘道器喔 🚨！", "P80": "🚇 utun（虛擬隧道網卡）：這是 Clash、Surge、小火箭、WireGuard 等代理軟體變出來的虛擬網卡 🪄。一旦它搶走了預設路由方向盤，所有流量都會先鑽進代理隧道；所以咱們才需要在代理規則裡把校園網段（10.0.0.0/8）設為直連（DIRECT）放行呀 🛣️✨！", "P81": "📡 無線 / 🔌 有線", "P82": "🛤️ 決定認證封包走哪條實體通道。插網路線（有線）和連 JLU.PC 共用同一套固定位址與帳號密碼 💳；而 JLU.WIFI 則是輕鬆愉快的動態網頁認證，單算一套 🌐✨。", "P83": "🚀 測速單位（Mbps）", "P84": "🤓 科普小課堂：小寫的 b（位元）和大寫的 B（位元組）差了整整 8 倍喔（1 位元組 = 8 位元）！平時電信商宣傳的「百兆寬頻」指的是 100 Mbps，換算成咱們下載軟體裡看到的實際速度 MB/s，記得要除以 8 才是真實水準哈 🧮✨！", "P85": "🏓 Ping 延遲（ms 毫秒）", "P86": "⏱️ 資料封包跑一個來回要花多少毫秒。在咱們校園網內部溜達一般不到 10ms，快如閃電 ⚡；如果繞道去了代理或異地 VPN 就會明顯變慢 🐢，要是出現掉封包就說明這條路有點顛簸不穩啦 🎢。", "P87": "😭 {…}：全部逾時失聯啦（掉封包率 {…}% 💔）", "P88": "📊 %@：平均 %.0f ms（最快 %.0f / 最慢 %.0f，掉封包 %.0f%% ✨）", "P89": "🏡 住宅 / 電信商原生 IP", "P90": "🏢 機房 IP（公有雲 / 資料中心）", "P91": "📱 行動網路 IP", "P92": "❓ 類型神秘未知", "P93": "· 🚨 已被標記為代理", "P94": "🏢 機房 IP 警告：去訪問 Claude、網路銀行或者串流媒體網站時，被吃閉門羹拒絕的機率會高很多喔 😭💦", "P95": "🚨 已經有公開的反詐欺資料庫把這個 IP 記在小本本上，標成代理或 VPN 出口啦 📝", "P96": "🤔 咦，IP 戶口名簿上的歸屬國({…}) 和 Cloudflare 測出來的機房所在國({…}) 對不上號呢，這多半是個廣播 IP 或者中轉線路喔 📡！", "P97": "🇨🇳 出口還在中國大陸境內喔：那些傲嬌的境外網站可能會直接按地區把你拒之門外 🚧", "P98": "🇨🇳 中國", "P99": "🇨🇳 中國大陸", "R01": "🌙 還有 {…} 分鐘宿舍就要斷電囉（週日到週四 23:30 準時熄燈）。檔案先存好 💾，手機插上充電 🔌，刷完牙就鑽進被窩吧 😴💤", "R02": "😴 只剩 {…} 分鐘就要斷電啦！趕快儲存、關燈、躺平——晚安，做個好夢 🌙✨", "R03": "🎉 週五、週六晚上不斷電，可以多玩一會兒～不過也別熬太狠呀，手機記得充電 🔌🌙", "R04": "🌙 已經熄燈啦，螢幕的光會晃到室友的眼睛 👀 早點休息，明天還要早起呢 😴💤", "R05": "☀️ 早八時間到！起床洗漱、路上買個熱呼呼的早餐 🥐，今天也要元氣滿滿地出門呀 🏃‍♂️✨", "R06": "🛌 今天早上沒有早八課～放心睡個美美的回籠覺吧，不過早餐還是要吃的喔 🥐😴✨", "R07": "🔔 放學啦！今天的課辛苦啦～去食堂吃頓熱呼呼的 🍜，或者回宿舍躺一小會兒 🛌，晚上還有力氣再戰 ✨", "R08": "🧰 網路診斷", "R09": "🪪 校園卡（實體卡）", "R10": "開學報到時統一發，不用自己買。澡堂刷熱水、圖書館門禁都用它。丟了要自己去線下繳費補辦喔 💸", "R11": "📱 電話卡（別和校園卡搞混）", "R12": "開學初會有電信業者來推銷「校園卡」，其實和學校那張實體卡一點關係都沒有，只是推銷話術。依自己的流量需求決定辦不辦，流量夠用就完全不用辦，不強制。", "R13": "🌐 校園網（收費，但不是必須）", "R14": "20 元/月，一般按學期繳 100 元。辦了可以連各校區的無線，宿舍的有線也能用。不強制，但有些校內網站只有在校園網裡才打得開。", "R15": "🎒 新生小提醒", "R16": "🔁 開機自動啟動還沒打開，重啟後要自己再開一次 App", "R17": "去設定裡打開", "R18": "開機自動啟動", "R19": "照著下面的步驟走一遍（macOS 26 和 14/15 的叫法略有不同）：", "R20": "✅ 已開啟：重啟後會自動出現", "R21": "⚠️ 還沒開啟：重啟後不會自己啟動", "R22": "⏳ 已登記，但需要你在「系統設定 → 登入項目與擴充功能」裡點一下允許", "R23": "📦 你用的是 SD 卡/下載目錄裡的便攜副本，不能開機自動啟動；把它拖進「應用程式」再打開，然後回來開這個開關", "R24": "打開系統設定 → 登入項目", "R25": "現在打開", "R26": "1️⃣ 點左上角蘋果選單  → 「系統設定」\n2️⃣ 左側點「一般」\n3️⃣ 右側點「登入項目與擴充功能」（macOS 14/15 裡叫「登入項目」）\n4️⃣ 在「登入時打開」那一欄找到「JLU Gate」，把右邊的開關打開\n5️⃣ 列表裡沒有它？點這一欄下面的「＋」，在彈出視窗選「應用程式」→ 找到「JLU Gate」→「打開」\n6️⃣ 如果提示「需要批准」，點「允許」，再輸一次密碼或按指紋\n7️⃣ 回到這裡看到「✅ 已開啟」就成功了\n⚠️ 前提：App 必須在「應用程式」資料夾裡；放在 SD 卡或下載目錄裡，系統不會把它加進登入項目", "S01": "🌱 萌新指南 / 第一次用看這裡", "S02": "👤 帳號", "S03": "📧 學校信箱前綴（比如 zhangcyy2122 或 zhangshanwu ✨）", "S04": "🔐 密碼（安全鎖在 Keychain 鑰匙圈裡 🛡️）", "S05": "留空不填 = 繼續用之前存好的密碼（{…}）💖", "S06": "🛤️ 鏈路設定", "S07": "🚪 接入方式", "S08": "🤖 自動判斷", "S09": "🔌 有線網路", "S10": "👀 認準 Wi-Fi 名字，必須一模一樣：JLU.PC / JLU.WIFI（大寫字母、中間帶個點 🟢）；", "S11": "⚠️ 遇到同名網路先留個心眼確認是不是學校的，可疑網路裡千萬別輸帳號喔 🛡️！", "S12": "🚀 通道底層實現", "S13": "🦅 BSD（預設首選，最貼近官方客戶端的原汁原味 ✨）", "S14": "🍎 NW（蘋果系統的網路框架）", "S15": "🤓 BSD：用原始 socket，能超精準地鎖死來源連接埠 61440 和指定網卡（IP_BOUND_IF）🎯；", "S16": "🍎 NW：走系統的 Network.framework，聽系統路徑管理的話。其實倆人發的是一樣的 UDP 封包 📦，", "S17": "平時預設用 BSD 就好 👍，哪天遇到系統傲嬌限制了再換 NW 試試 🔄！", "S18": "📌 固定網路參數（只在有線 / JLU.PC 下派上用場 🛠️）", "S19": "🎉 你現在選的是 JLU.WIFI：位址動態分配 + 網頁認證，下面這些複雜的靜態參數統統不用管啦 🏖️！", "S20": "📝 學校分給你的專屬固定位址，照著通知單抄就行（別抄成 DHCP 自動分的喔 🙅‍♂️）", "S21": "🎭 子網路遮罩", "S22": "一般填 255.255.255.0 準沒錯 ✨", "S23": "🚪 閘道器", "S24": "同網段的第一跳 🦘，通常是 x.x.x.254", "S25": "🏫 校內推薦用 10.10.10.10；到了校外可以換成 223.5.5.5 🌐✨", "S26": "🪪 登記 MAC", "S27": "在學校登記的那塊網卡的真實實體位址（別填成系統隨機產生的假 MAC 喔 🕵️‍♂️）", "S28": "🐢 相容模式：關掉酷炫的液態玻璃特效（在虛擬機或老顯示卡上跑得更穩當，重啟 App 生效喔 🔄✨）", "S29": "🎭 當系統開了私有/隨機 MAC 時，強行用登記的 MAC 去發認證封包（高階魔法 🪄）", "S30": "這招只改認證信件裡的 MAC 簽名 ✉️，不動網卡本身。不過最穩妥的辦法還是去系統設定裡把「私人 Wi-Fi 位址」關掉啦 👍✨！", "S31": "📋 靜態網路參數", "S32": "👀 系統目前讀數（僅供參考核對喔）", "S33": "🧭 路由：{…}", "S34": "🎴 網卡選擇", "S35": "👉 派哪塊網卡出戰？", "S36": "🤖 自動挑選（按 MAC 認領 ✨）", "S37": "🎯 按登記的 MAC 自動幫你選一次", "S38": "📡 鏈路探測", "S39": "🚀 打開 App 時自動連線（記住帳號密碼後就安安靜靜幫你連，絕不打擾 🤫💖）", "S40": "🕵️‍♂️ 自動探測（悄悄發 1 個 challenge 封包看看是不是在校園網裡 ✨）", "S41": "關掉之後就只做普通的 204 探針檢測，絕不主動給校園閘道器發任何認證封包 🤐🛡️。", "S42": "🌐 網頁認證入口 URL（留空就會自動幫你找喔 🔍）", "S43": "🛡️ 路由保障", "S44": "📍 目前狀態：{…}", "S45": "🦸‍♂️ 允許背景小幫手新增 -ifscope 直連路由（需要管理員點個頭授權喔 🔑）", "S46": "🚧 背景 helper 屬於 M2.5 階段的酷炫功能，這個版本還沒帶上它；沒授權時咱們會貼心地給你一條可以複製的指令 📋✨。", "S47": "🌟 版本更新", "S48": "🔍 檢查更新", "S49": "🏷️ 目前版本 {…}", "S50": "🧪 進階玩家區", "S51": "🖥️ 伺服器位址", "S52": "🔌 伺服器連接埠", "S53": "🔒 本機連接埠（必須鎖死 61440 喔）", "S54": "🌅 開機自動啟動", "S55": "💾 儲存設定", "S56": "✅ 存好啦！", "S57": "✖️ 關閉", "S58": "📥 讀取系統目前值", "S59": "🔄 重新檢測一下", "S60": "📋 匯入參數卡", "S61": "🧹 清空網路參數", "S62": "🗑️ 忘掉已儲存的密碼", "S63": "💥 重置本機所有設定…", "S64": "⏳ 正在努力檢查中…", "S65": "🎉 已經是最新版啦！", "S66": "🎁 發現新版本 {…}！", "S67": "🚀 下載並立刻安裝", "S68": "📥 先只下載不安裝", "S69": "🟢 A 層 · 出口正好就是 {…}，不用任何特權就能絲滑使用 ✨！", "S70": "🔵 B 層 · 由貼心的 helper 給 {…} 加上 /32 專屬路由 🛣️", "S71": "🟡 C 層 · 需要你搭把手，手動給 {…} 加一條路由指令 ✍️", "S72": "🔴 拿不到路由資訊呢（可能是網卡還在睡懶覺，或者沒找到去伺服器的路 🗺️💤）", "S73": "⚪ 還沒檢測過呢 🐣", "T01": "🌟 吉大人生存必備常用站點", "T02": "🔍 搜搜站點名字、網域或者你想幹嘛…", "T03": "💡 標著「僅校內」的站點在外面是打不開的喔，得先連上 WebVPN 🌉；標著「需 VPN」意思是網頁能打開，但裡面的核心資源（比如知網論文 📚）需要校園網環境才能看 ✨。", "T04": "🙈 翻遍了也沒找到匹配的站點呢，換個詞試試？", "T05": "📰 校園網入口網站 / 今日份校園小廣告", "T06": "🌐 打開入口網站看看", "T07": "每次認證完，學校經常會熱情地彈一個歡迎/通知頁 🎉；咱們這兒不煩人地自動彈窗，直接把網址留給你，想看的時候隨時點開用瀏覽器看 👀✨！", "T08": "🏛️ 我的專屬學院", "T09": "🚀 打開學院官網", "T10": "🔄 換個學院", "T11": "✍️ 填一下學號，或者手動選一次學院，以後小幫手就能一眼認出你的學院啦（放心，只乖乖存在你自己的電腦裡 🔒✨）", "T12": "🎓 你的學號", "T13": "🔍 搜搜學院名字或網域…", "T14": "📂 展開全部 {…} 個學院大家庭", "T15": "🏫 咱們吉大一共有 {…} 個學院呢 ✨", "T16": "🎯 找到了 {…} 個匹配的學院，先給你展示前 6 個；繼續打字可以縮小範圍，或者直接點下面全部展開喔 👇✨", "T17": "🎯 匹配到 {…} 個結果", "T18": "🚀 打開", "T19": "📋 複製帳號", "T20": "🔑 複製密碼", "T21": "哎呀 🙈，你還從來沒填過帳號呢——先去「設定」裡填一次吧 ✍️✨！", "T22": "✅ 帳號已經複製到剪貼簿啦：{…} 🎉", "T23": "咦 🤔？電腦裡還沒有儲存過密碼呢——先去「設定」裡儲存一次吧 💾✨！", "T24": "🔐 密碼已成功複製！為了安全，60 秒後會自動幫你清空剪貼簿喔 ⏱️🛡️", "TD01": "🌍 公網暢行", "TD02": "🏫 僅限校內", "TD03": "🌉 需連 VPN", "TD04": "📖 學習與教務", "TD05": "💼 辦事與校務", "TD06": "✉️ 校園信箱", "TD07": "🌐 校園網服務", "TD08": "📰 資訊與官網", "TD09": "🎓 智慧校園（教務系統）", "TD10": "搶課 🏃‍♂️、看課表 📅、查成績 💯、看考試安排都在這兒！", "TD11": "🏛️ 本科生院", "TD12": "重要的教學通知 📢、培養方案、還有學籍相關文件 📂", "TD13": "🧪 研究生院", "TD14": "研究生培養計畫、學位申請與招生通知 🎓✨", "TD15": "📚 圖書館", "TD16": "查借書紀錄 📖、進文獻資料庫（下論文記得連校園網或 VPN 喔 🌉）", "TD17": "📋 電子校務平台（